 // EVH-21: Pruebas automatizadas del registro de ponentes

// Comprobar que el servidor responda con 201 Created
pm.test("Registro exitoso - Codigo 201", function () {
    pm.response.to.have.status(201);
});

// Obtener el JSON de la respuesta del servidor
const speaker = pm.response.json();

// Verificar que el ponente tenga un identificador UUID
pm.test("El ponente tiene un UUID valido", function () {
    pm.expect(speaker.id).to.match(
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
    );
});

// Comprobar que el servidor devuelva el correo registrado
pm.test("El correo registrado es correcto", function () {
    pm.expect(speaker.email).to.eql("ana.torres.prueba@ipn.mx");
});

// Verificar la cabecera Location
pm.test("La respuesta incluye la cabecera Location", function () {
    pm.expect(pm.response.headers.get("Location"))
      .to.eql("/api/v1/speakers/" + speaker.id);
});

// Guardar el identificador para utilizarlo en otras pruebas
if (pm.response.code === 201 && speaker.id) {
    pm.collectionVariables.set("speakerId", speaker.id);
}

 // EVH-21: Prueba de campos obligatorios faltantes

// Comprobar que el servidor rechace la solicitud con HTTP 400
pm.test("Codigo HTTP 400 Bad Request", function () {
    pm.response.to.have.status(400);
});

// Obtener la respuesta JSON del servidor
const response = pm.response.json();

// Verificar que el error tenga el codigo esperado
pm.test("Codigo de error VALIDATION_ERROR", function () {
    pm.expect(response.error.code).to.eql("VALIDATION_ERROR");
});

// Comprobar que el mensaje indique los campos obligatorios
pm.test("Mensaje de campos obligatorios", function () {
    pm.expect(response.error.message).to.include(
        "Todos los campos son obligatorios"
    );
});

// Verificar que la respuesta tenga el formato estandar
pm.test("Formato de error correcto", function () {
    pm.expect(response.error.status).to.eql(400);
    pm.expect(response.error).to.have.property("timestamp");
    pm.expect(response.error.timestamp).to.be.a("string");
});

 // EVH-21: Prueba de correo con formato invalido

// Verificar que el servidor responda con 400
pm.test("Codigo HTTP 400 Bad Request", function () {
    pm.response.to.have.status(400);
});

// Obtener la respuesta del servidor
const response = pm.response.json();

// Verificar el codigo del error
pm.test("Codigo VALIDATION_ERROR", function () {
    pm.expect(response.error.code).to.eql("VALIDATION_ERROR");
});

// Comprobar el mensaje de correo invalido
pm.test("Mensaje de correo invalido", function () {
    pm.expect(response.error.message).to.eql(
        "El formato del correo electrónico no es válido"
    );
});

// Comprobar la estructura del error
pm.test("Formato de error correcto", function () {
    pm.expect(response.error.status).to.eql(400);
    pm.expect(response.error.timestamp).to.be.a("string");
});

 // EVH-21: Validación de correo duplicado

pm.test("Codigo HTTP 409 Conflict", function () {
    pm.response.to.have.status(409);
});

const response = pm.response.json();

pm.test("Codigo DUPLICATE_EMAIL", function () {
    pm.expect(response.error.code).to.eql("DUPLICATE_EMAIL");
});

pm.test("Mensaje de correo duplicado", function () {
    pm.expect(response.error.message).to.eql(
        "El correo electrónico ya está registrado"
    );
});

pm.test("Formato de error correcto", function () {
    pm.expect(response.error.status).to.eql(409);
    pm.expect(response.error.timestamp).to.be.a("string");
});
